select id, cell
from b_wuba_colliding_data_loop_cycle
where is_deleted = 0
  and api_code = #{apiCode}
   and push_time >= #{pushTimeStart} and push_time < #{pushTimeEnd} 
order by push_time
limit #{pageSize}

